const j = $input.first().json;
const meta = j.metadata || {};
const fromRaw = String(j.from || meta.from || '');
const m = fromRaw.match(/<([^>]+)>/);
const from_email = (m ? m[1] : fromRaw).trim().toLowerCase();
const from_name = (m ? fromRaw.replace(/<[^>]+>/, '') : '').replace(/["']/g, '').trim() || null;
let body = j.textPlain || '';
if (!body && j.textHtml) body = String(j.textHtml).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
// strip the demo routing tag from the subject so downstream sees a natural subject
const subject = String(j.subject || meta.subject || '').replace(/\[enquiry\]\s*/i, '').trim();
return [{ json: {
  to_raw: String(j.to || meta.to || ''),
  from_email,
  from_name,
  subject,
  body,
  received_at: j.date || meta.date || null,
  external_id: 'gmail-' + String(j.messageId || meta.messageId || Date.now())
} }];

